package blockbranch.realistic;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.levelgen.structure.BoundingBox;
/** Actual two-block headroom routes; jungle includes its explicit one-block bridge jumps. */
final class ReimaginedRoutes {
 static int verify(ServerLevel level,ReimaginedLayoutPiece piece){var tag=piece.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level));int entry=tag.getIntOr("EntryHeight",18);int[][] points=switch(piece.kind()){case 1->new int[][]{{8,0,0},{-17,0,0},{10,0,-10},{0,0,-18},{-24,0,0}};case 2->tag.getIntOr("PyramidReplacement",0)>0?new int[][]{{10,entry+1,-24},{10,18,8},{-2,18,4},{-2,-4,27},{10,1,1},{10,1,7},{-7,-5,-7},{27,-5,10},{6,-5,10}}:new int[][]{{4,entry+1,-24},{18,-5,-7},{-7,-5,-7},{6,-5,10},{27,-5,10}};default->new int[][]{{-9,0,0},{-4,10,2},{-1,10,2},{15,10,13},{20,10,14},{0,19,20},{-9,19,2},{17,19,20}};};return walk(level,piece.getBoundingBox(),Arrays.stream(points).map(p->piece.local(p[0],p[1],p[2])).toList(),piece.kind()==3);}
 static int mansion(ServerLevel level,ReimaginedMansionPiece piece){var tag=piece.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level));int[] b=tag.getIntArray("Core").orElseThrow();int y=tag.getIntOr("Floor",0),x0=b[0]-10,x1=b[3]+10,z0=b[2]-10,z1=b[5]+10;return walk(level,piece.getBoundingBox(),List.of(new BlockPos((x0+x1)/2,y,z0),new BlockPos(x0+4,y+9,z0+13),new BlockPos(x0+1,y+9,z1-5),new BlockPos(x1-1,y+9,z1-5),new BlockPos(x1-1,y+9,z0+5)),false);}
 static int servicePassage(ServerLevel level,ReimaginedMansionPiece piece,boolean reload){var tag=piece.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level));var a=tag.getIntArray("Passage").orElseThrow();require(a.length==6,"Saved concealed passage endpoints");var ends=List.of(new BlockPos(a[0],a[1],a[2]),new BlockPos(a[3],a[4],a[5]));for(var end:ends){var hatch=end.below();require(level.getBlockState(hatch).is(net.minecraft.world.level.block.Blocks.OAK_TRAPDOOR),"Native service hatch");if(!reload){var player=new net.minecraft.server.level.ServerPlayer(level.getServer(),level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"ServiceRoute"),net.minecraft.server.level.ClientInformation.createDefault());player.setPos(end.getX()+.5,end.getY(),end.getZ()+.5);player.gameMode.useItemOn(player,level,net.minecraft.world.item.ItemStack.EMPTY,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(hatch),net.minecraft.core.Direction.UP,hatch,false));}require(level.getBlockState(hatch).getValue(net.minecraft.world.level.block.TrapDoorBlock.OPEN),"Actual native hatch interaction/open state persisted");}
 var visited=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();visited.add(ends.getFirst());queue.add(ends.getFirst());while(!queue.isEmpty()){var p=queue.removeFirst();for(var direction:net.minecraft.core.Direction.values()){var n=p.relative(direction);if(!piece.getBoundingBox().isInside(n)||visited.contains(n)||!passageClear(level,n)||!passageClear(level,n.above()))continue;boolean climb=climb(level,p)||climb(level,n);if(direction.getAxis().isVertical()&&!climb)continue;if(passageClear(level,n.below())&&!climb)continue;visited.add(n);queue.add(n);}}require(visited.contains(ends.getLast()),"Concealed service passage reaches native foyer through actual ladders "+visited.size());return visited.size();}
 private static boolean climb(ServerLevel l,BlockPos p){for(var at:List.of(p,p.below(),p.above())){var s=l.getBlockState(at);if(s.is(net.minecraft.world.level.block.Blocks.LADDER)||s.is(net.minecraft.world.level.block.Blocks.OAK_TRAPDOOR)&&s.getValue(net.minecraft.world.level.block.TrapDoorBlock.OPEN))return true;}return false;}
 private static boolean passageClear(ServerLevel l,BlockPos p){var s=l.getBlockState(p);return clear(l,p)||s.is(net.minecraft.world.level.block.Blocks.LADDER)||s.is(net.minecraft.world.level.block.Blocks.OAK_TRAPDOOR)&&s.getValue(net.minecraft.world.level.block.TrapDoorBlock.OPEN);}
 static int sanctuary(ServerLevel level,ReimaginedSanctuaryPiece piece){int cells=0;for(int y:new int[]{2,13})for(int t=-9;t<=66;t++)for(int[] p:new int[][]{{t,-9},{t,66},{-9,t},{66,t}}){var at=piece.local(p[0],y,p[1]);require(level.getBlockState(at).is(net.minecraft.world.level.block.Blocks.WATER),"Continuous flooded ring "+at+" "+level.getBlockState(at));cells++;}for(int y=2;y<=13;y++)for(int[] p:new int[][]{{-10,-10},{67,-10},{-10,67},{67,67}}){var at=piece.local(p[0],y,p[1]);require(level.getBlockState(at).is(net.minecraft.world.level.block.Blocks.WATER),"Open vertical sanctuary route "+at);cells++;}return cells;}
 private static int walk(ServerLevel level,BoundingBox box,List<BlockPos> points,boolean jumps){var origin=points.getFirst();require(stand(level,origin),"route start headroom "+origin);var visited=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();visited.add(origin);queue.add(origin);while(!queue.isEmpty()){var p=queue.removeFirst();for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})for(int distance=1;distance<=(jumps?2:1);distance++)for(int dy:new int[]{0,1,-1}){var n=p.offset(d[0]*distance,dy,d[1]*distance);if(!box.isInside(n)||visited.contains(n)||!stand(level,n))continue;if(dy>0&&!clear(level,p.above(2)))continue;if(distance==2){var middle=p.offset(d[0],Math.max(0,dy),d[1]);if(!clear(level,middle)||!clear(level,middle.above())||!clear(level,p.above(2)))continue;}visited.add(n);queue.add(n);}}for(var p:points)require(visited.contains(p),"connected architectural route "+p+" visited="+visited.size());return visited.size();}
 private static boolean clear(ServerLevel l,BlockPos p){return l.getBlockState(p).getCollisionShape(l,p).isEmpty();}
 private static boolean stand(ServerLevel l,BlockPos p){return clear(l,p)&&clear(l,p.above())&&!clear(l,p.below());}
 private static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
